fn solve(m: i8, d: i8) -> i8 {
    // Fixed month lengths for a non-leap year
    let days_in_month = match m {
        1 => 31,  // January
        2 => 28,  // February
        3 => 31,  // March
        4 => 30,  // April
        5 => 31,  // May
        6 => 30,  // June
        7 => 31,  // July
        8 => 31,  // August
        9 => 30,  // September
        10 => 31, // October
        11 => 30, // November
        12 => 31, // December
        _ => 0,   // invalid month, though problem states input is always valid
    };

    // Calculate total spaces needed including leading weekdays before first day
    // Formula: weeks = 1 + floor((d - 1 + days_in_month - 1) / 7)
    //         = ceil((d - 1 + days_in_month) / 7)
    let total_days = (d - 1) + days_in_month;
    let weeks = (total_days + 6) / 7; // integer division with ceiling trick

    weeks
}